def aabb(cx, cy, hx, hy):
    return (cx, cy, hx, hy)

def test(a, b):
    """Ortusme varsa (True, eksen, derinlik), yoksa (False, None, bosluk)."""
    ox = (a[2] + b[2]) - abs(a[0] - b[0])
    oy = (a[3] + b[3]) - abs(a[1] - b[1])
    if ox <= 0 or oy <= 0:
        return (False, None, round(min(ox, oy), 4))
    return (True, "x" if ox < oy else "y", round(min(ox, oy), 4))

