DT = 1.0 / 60.0

def isin_aabb(ox, oy, dx, dy, minx, miny, maxx, maxy):
    """Slab yontemi: her eksende giris/cikis parametreleri kesistirilir."""
    tmin, tmax = 0.0, 1e18
    for o, d, lo, hi in ((ox, dx, minx, maxx), (oy, dy, miny, maxy)):
        if d == 0.0:
            if o < lo or o > hi:
                return None
            continue
        t1, t2 = (lo - o) / d, (hi - o) / d
        if t1 > t2:
            t1, t2 = t2, t1
        tmin = max(tmin, t1)
        tmax = min(tmax, t2)
        if tmin > tmax:
            return None
    return round(tmin, 4), round(tmax, 4)

