SLOP = 0.01       # tolere edilen penetrasyon
ORAN = 0.8        # kare basina duzeltme yuzdesi

def penetrasyon_duzelt(pen, m1, m2):
    im1 = 0.0 if m1 == 0.0 else 1.0 / m1
    im2 = 0.0 if m2 == 0.0 else 1.0 / m2
    d = max(pen - SLOP, 0.0) * ORAN / (im1 + im2)
    return round(d * im1, 4), round(d * im2, 4)

