DT = 1.0 / 60.0
GECIS = 0.15                    # capraz gecis suresi (s)

def smoothstep(t):
    t = 0.0 if t < 0.0 else (1.0 if t > 1.0 else t)
    return t * t * (3.0 - 2.0 * t)

class Karistirici:
    def __init__(self, klip):
        self.suren, self.gelen, self.t = klip, None, 0.0

    def gec(self, klip):
        if klip == self.suren or klip == self.gelen:
            return                       # ayni klibe yeniden gecis yok
        self.gelen, self.t = klip, 0.0

    def ilerle(self):
        if self.gelen is None:
            return self.suren, 1.0, None, 0.0
        self.t += DT
        w = smoothstep(self.t / GECIS)
        if self.t >= GECIS:
            self.suren, self.gelen, self.t = self.gelen, None, 0.0
            return self.suren, 1.0, None, 0.0
        return self.suren, round(1.0 - w, 4), self.gelen, round(w, 4)

