ATIS_KARE = 3          # her 3 karede bir mermi  (60/3 = 20 atis/s)
OMUR_KARE = 90         # mermi omru 1.5 s
KARE = 600             # 10 saniyelik sim

class Havuz:
    def __init__(self, boyut):
        self.serbest = list(range(boyut))
        self.ayirma = boyut        # baslangicta bir kez ayrildi
        self.tasma = 0
        self.tepe = 0
        self.kullanim = 0

    def al(self):
        if self.serbest:
            i = self.serbest.pop()
        else:
            i = -1                 # havuz bos: yeni nesne ayrilmak zorunda
            self.tasma += 1
            self.ayirma += 1
        self.kullanim += 1
        self.tepe = max(self.tepe, self.kullanim)
        return i

    def birak(self, i):
        self.kullanim -= 1
        if i >= 0:
            self.serbest.append(i)

def calistir(boyut):
    h = Havuz(boyut)
    canli = []                     # [kimlik, olum_karesi]
    havuzsuz = 0
    for k in range(KARE):
        for kayit in list(canli):
            if kayit[1] <= k:
                canli.remove(kayit)
                h.birak(kayit[0])
        if k % ATIS_KARE == 0:
            canli.append([h.al(), k + OMUR_KARE])
            havuzsuz += 1
    return h.tepe, h.ayirma, h.tasma, havuzsuz

