def yukle(kayit):
    s = kayit.get("surum", 1)
    if s > GUNCEL:
        return "HATA: daha yeni surum (%d)" % s
    adim = 0
    while s < GUNCEL:
        kayit = GECISLER[s](kayit)
        s += 1
        kayit["surum"] = s
        adim += 1
    return adim, kayit

