import math

def iki_oran_testi(nA, pA, nB, pB):
    """Iki orani karsilastiran z testi; kutuphane yok, math.erf yeterli."""
    p = (nA * pA + nB * pB) / (nA + nB)
    se = math.sqrt(p * (1 - p) * (1.0 / nA + 1.0 / nB))
    z = (pB - pA) / se
    pdeger = 2 * (1 - 0.5 * (1 + math.erf(abs(z) / math.sqrt(2))))
    return round(p, 5), round(se, 6), round(z, 4), round(pdeger, 5)

for ad, nA, pA, nB, pB in (("kucuk ornek", 1200, 0.385, 1200, 0.421),
                           ("buyuk ornek", 6000, 0.385, 6000, 0.421)):
    p, se, z, pd = iki_oran_testi(nA, pA, nB, pB)
    print("%s n=%d  p=%.5f se=%.6f z=%.4f p-deger=%.5f anlamli=%s"
          % (ad, nA, p, se, z, pd, pd < 0.05))

def gerekli_n(p, fark, guc_z=0.84, alfa_z=1.96):
    return math.ceil(2 * ((alfa_z + guc_z) ** 2) * p * (1 - p) / (fark * fark))

